export SETS="rg,robust_zh,robust_para,robust_func,robust_vague,refcoco_val,refcocog_val,grefcoco_val_merged"
while pgrep -f '[b]ase_gen.py|[e]val.py|[t]rain.py' > /dev/null; do sleep 30; done  # one GPU job at a time
bash /content/dv/scripts/sprint_robust/run_recipe.sh
